WFJ.Data.add("quest", {
  [8234] = { "⟦Sealed Azure Bag=Sacca Azzurra Chiusa⟧", "Recupera la ⟦Sealed Azure Bag=Sacca Azzurra Chiusa⟧ dal Timbermaw Shaman ad Azshara. Poi porta la sacca all'arcimago Xylem, che si trova anche lui ad Azshara.", "Prima le cose importanti. Ciò che ho perso è una piccola sacca blu, il cui contenuto è una faccenda privata.\n\nNon perdere tempo a inseguire i ladri, perché sono già morti. Quello che sappiamo è che quegli sciocchi non sono riusciti ad aprire la sacca, così l'hanno venduta a un timbermaw shaman ad Azshara come reliquia sacra. Astuti.\n\nHo bisogno che tu vada ad Azshara e la recuperi da quello shaman con la discrezione... o con la forza. Scommetto che avrai più fortuna con il primo metodo. Una volta presa, portala all'arcimago Xylem.", "Ci conosciamo?", "Vedo che hai la sacca di lord Ravenholdt. Perché non l'hai detto subito, <ragazzo/ragazza>?", 0x35599650, 0x0ea5890f, 0xfe836e00, 0x879570ca, 0x860f19ff, ".....", nil, nil, nil, nil, 0xf0af4ecb },
  [8274] = { "Missione di prova di uccisione", "Uccidi 5 Murloc e torna dal personaggio di prova.", "Hai un po' di tempo libero? Uccidimi qualche Murloc e ti darò qualcosa di luccicante!", nil, nil, 0x2cbcf304, 0x00bf1e49, 0xa551eef6, nil, nil, "...mm" },
  [8290] = { "Sconfiggere gli invasori", "Entra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e sconfiggi l'⟦Horde=Orda⟧, ottieni un ⟦Warsong Gulch Mark of Honor=Contrassegno d'Onore della Forra dei Cantaguerra⟧ e torna dalla sentinella Farsong al ⟦Silverwing Grove=Boschetto degli Alargentea⟧.", "Oltre questa galleria troverai un campo di lotta e tumulto, giovane {class}. L'⟦Horde=Orda⟧ continua a devastare la nostra foresta sacra, abbattendo i sempreverdi per alimentare le sue macchine da guerra.\n\nEntra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e difendi la ⟦Silverwing Hold=Rocca di Alargentea⟧. Respingi le forze d'invasione dell'⟦Horde=Orda⟧!\n\nFallo, e otterrai un talismano al merito. Portami un tale talismano, {name}, e ti ricompenserò.", nil, nil, 0x877db1ee, 0xfeb46d9a, 0xd5134582, nil, nil, "...mm" },
  [8291] = { "Sconfiggi gli invasori!", "Entra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e sconfiggi l'⟦Horde=Orda⟧, ottieni le ⟦Silverwing Talisman of Merit=Medaglie al Valore degli Alargentea⟧ e torna dalla sentinella Farsong al ⟦Silverwing Grove=Boschetto degli Alargentea⟧.", "Oltre questa galleria troverai un campo di lotta e tumulto, giovane {class}. L'⟦Horde=Orda⟧ continua a devastare la nostra foresta sacra, abbattendo i sempreverdi per alimentare le sue macchine da guerra.\n\nEntra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e difendi la ⟦Silverwing Hold=Rocca di Alargentea⟧. Respingi le forze d'invasione dell'⟦Horde=Orda⟧!\n\nFallo, e otterrai un talismano al merito. Portami un tale talismano, {name}, e ti ricompenserò.", "Hai combattuto nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e difeso la ⟦Silverwing Hold=Rocca di Alargentea⟧?", "Hai dimostrato il tuo valore nei nostri sforzi nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧. Continua a sostenere la causa e portami altri contrassegni d'onore. Fallo, e ti guadagnerai ancora di più la nostra fiducia.", 0x55520e44, 0xbdddd230, 0xd5134582, 0x71ff749c, 0xf9915c4e, "....." },
  [8294] = { "Domare gli usurpatori Alargentea", "Entra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e sconfiggi l'⟦Alliance=Alleanza⟧, ottieni un Contrassegno d'Onore dei ⟦Warsong=Cantaguerra⟧ e portalo al capitano Shatterskull all'⟦Mor'shan Base Camp=Accampamento Mor'shan⟧.", "Le terre selvagge della foresta di ⟦Ashenvale=Valtetra⟧ cederanno alla potenza dell'⟦Horde=Orda⟧, {race}. Nulla di ciò che gli Alargentea dicono o fanno può fermare il nostro imperativo sovrano. Kalimdor appartiene all'⟦Horde=Orda⟧. Come osano cercare di impedirci di raccogliere ciò che è nostro di diritto!\n\nLascia che l'orgoglio ti gonfi il petto mentre stronchi i loro deboli tentativi di rallentare la nostra avanzata. Distruggi le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ e ottieni un contrassegno d'onore dei ⟦Warsong=Cantaguerra⟧. Torna da me con un tale contrassegno, {name}, e sarai ricompensat<o/a>.", "Il sangue dei nostri nemici è un contrassegno d'onore. Ce l'hai un contrassegno del genere?", "<Il capitano Shatterskull ruggisce in trionfo.>\n\nQuanto ancora possono resistere? Quanta altra feccia dell'⟦Alliance=Alleanza⟧ deve perire per mano dell'⟦Horde=Orda⟧ prima che si ritirino? Solo il tempo lo dirà, {race}...", 0x636625b4, 0x3df29510, 0x2eb6ef0c, 0xd1cff4b7, 0x160777a5, "....." },
  [8295] = { "Domare gli usurpatori Alargentea", "Entra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e sconfiggi l'⟦Alliance=Alleanza⟧, ottieni un ⟦Warsong Gulch Mark of Honor=Contrassegno d'Onore della Forra dei Cantaguerra⟧ e portalo al capitano Shatterskull all'⟦Mor'shan Base Camp=Accampamento Mor'shan⟧.", "Le terre selvagge della foresta di ⟦Ashenvale=Valtetra⟧ cederanno alla potenza dell'⟦Horde=Orda⟧, {race}. Nulla di ciò che gli Alargentea dicono o fanno può fermare il nostro imperativo sovrano. Kalimdor appartiene all'⟦Horde=Orda⟧. Come osano cercare di impedirci di raccogliere ciò che è nostro di diritto!\n\nLascia che l'orgoglio ti gonfi il petto mentre stronchi i loro deboli tentativi di rallentare la nostra avanzata. Distruggi le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ e ottieni un contrassegno d'onore dei ⟦Warsong=Cantaguerra⟧. Torna da me con un tale contrassegno, {name}, e sarai ricompensat<o/a>.", nil, nil, 0x636625b4, 0xc94c2293, 0x2eb6ef0c, nil, nil, "...mm" },
  [8368] = { "La battaglia della ⟦Warsong Gulch=Forra dei Cantaguerra⟧", "Porta 3 Marchi d'Onore dei ⟦Warsong=Cantaguerra⟧ a un Warbringer dell'⟦Horde=Orda⟧ fuori dai campi di battaglia.", "La battaglia nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ contro le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ è di grande importanza. Con il pretesto di proteggere una foresta che non le appartiene, l'⟦Alliance=Alleanza⟧ cerca di negare all'⟦Horde=Orda⟧ una delle nostre maggiori fonti di legname.\n\nNon permettere che accada, {name}! Torna da me con la prova di aver servito l'⟦Horde=Orda⟧ in modo degno!", "Porti notizie dalla ⟦Warsong Gulch=Forra dei Cantaguerra⟧, {name}?", "Eccellente! Hai dimostrato il tuo valore difendendo le nostre operazioni nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧! Che la fama del tuo onore si diffonda in lungo e in largo per le nostre terre.", 0x6925d544, 0xdd9a4a31, 0x134a3898, 0x5bb7b09a, 0xf832f61b, "....." },
  [8372] = { "Lotta per la ⟦Warsong Gulch=Forra dei Cantaguerra⟧", "Porta 3 Marchi d'Onore della ⟦Warsong Gulch=Forra dei Cantaguerra⟧ a un generale di brigata dell'⟦Alliance=Alleanza⟧ fuori dai campi di battaglia.", "Le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ sono in guerra con i ⟦Warsong Outriders=Predoni Cantaguerra⟧ per la distruzione che gli orchi stanno causando alla foresta. Tuttavia, ci sono più ragioni per difendere questa foresta in particolare del semplice amore per la natura.\n\nLa foresta forma una barriera strategica che rende ⟦Ashenvale=Valtetra⟧ difendibile da un attacco su larga scala. Senza di essa, Astranaar resisterebbe un giorno o due prima di essere annessa alle ⟦Barrens=Savane⟧.\n\nFa' la tua parte nella lotta contro i ⟦Warsong Outriders=Predoni Cantaguerra⟧, {name}! Per l'⟦Alliance=Alleanza⟧!", "Sei <tornato/tornata> con notizie dal fronte, {name}?", "Ben fatto, {name}! Hai servito bene l'⟦Alliance=Alleanza⟧.", 0xbeadcb52, 0x169d4275, 0xd15c0916, 0x378bede6, 0xa2a5cb89, "....." },
  [8399] = { "Lotta per la ⟦Warsong Gulch=Forra dei Cantaguerra⟧", "Porta 3 Marchi d'Onore della ⟦Warsong Gulch=Forra dei Cantaguerra⟧ a un generale di brigata dell'⟦Alliance=Alleanza⟧ fuori dai campi di battaglia.", "Le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ sono in guerra con i ⟦Warsong Outriders=Predoni Cantaguerra⟧ per la distruzione che gli orchi stanno causando alla foresta. Tuttavia, ci sono più ragioni per difendere questa foresta in particolare del semplice amore per la natura.\n\nLa foresta forma una barriera strategica che rende ⟦Ashenvale=Valtetra⟧ difendibile da un attacco su larga scala. Senza di essa, Astranaar resisterebbe un giorno o due prima di essere annessa alle ⟦Barrens=Savane⟧.\n\nFa' la tua parte nella lotta contro i ⟦Warsong Outriders=Predoni Cantaguerra⟧, {name}! Per l'⟦Alliance=Alleanza⟧!", "Sei <tornato/tornata> con notizie dal fronte, {name}?", "Ottimo lavoro, {name}. Grazie a te, le nostre difese naturali a ⟦Ashenvale=Valtetra⟧ resteranno intatte per un altro giorno.", 0xbeadcb52, 0x169d4275, 0xd15c0916, 0x378bede6, 0x83c232b5, "....." },
