  [8430] = { "La battaglia della ⟦Warsong Gulch=Forra dei Cantaguerra⟧", "Porta 3 Marchi d'Onore della ⟦Warsong Gulch=Forra dei Cantaguerra⟧ a un araldo di guerra dell'⟦Horde=Orda⟧ fuori dai campi di battaglia.", "La battaglia nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ contro le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ è di grande importanza. Con il pretesto di proteggere una foresta che non le appartiene, l'⟦Alliance=Alleanza⟧ cerca di negare all'⟦Horde=Orda⟧ una delle nostre maggiori fonti di legname.\n\nNon permettere che accada, {name}! Torna da me con la prova di aver servito l'⟦Horde=Orda⟧ in modo degno!", "Porti notizie dalla ⟦Warsong Gulch=Forra dei Cantaguerra⟧, {name}?", "Eccellente! Hai dimostrato il tuo valore difendendo le nostre operazioni nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧! Che la fama del tuo onore si diffonda in lungo e in largo per le nostre terre.", 0x6925d544, 0xcff9743e, 0x134a3898, 0x5bb7b09a, 0xf832f61b, "....." },
  [8499] = { "L'⟦Alliance=Alleanza⟧ ha bisogno di barre di torio!", "Porta 20 Thorium Bar a dama Twinbraid nel Military Ward di ⟦Ironforge=Forgiardente⟧.", "È molto gentile da parte tua informarti sulle necessità dell'⟦Alliance=Alleanza⟧. Oltre a tutte le altre raccolte in corso, abbiamo bisogno di una grande quantità di barre di torio, ed è questo il compito di cui sono responsabile. Il torio servirà a creare molte cose diverse per la guerra, prima fra tutte la costruzione di un battaglione di carri armati a vapore da trasportare in volo a ⟦Silithus=Silitus⟧ non appena saranno completati. Puoi aiutarci in questa impresa, {class}?", "Oh, un carico da parte di mio fratello? Splendido! Oggi la fortuna mi sorride davvero!", "Quindi Gnoarn non si fida delle mie capacità di ricognizione? Chissà perché...", 0xbc047bca, 0x3b0fb51a, 0xde56c2df, 0x89b01d8f, 0x8c8ff225, "....." },
  [8565] = { "Vittorie passate ad Arathi", nil, nil, nil, "Ah, sì! Certo che non ci saremmo dimenticati delle tue imprese passate nel ⟦Arathi Basin=Bacino d'Arathi⟧.", 0x1b6fa606, nil, nil, nil, 0x84b7e476, ".mmm." },
  [8566] = { "Vittorie passate ad Arathi", nil, nil, nil, "Ah, sì! Certo che non ci saremmo dimenticati delle tue imprese passate nel ⟦Arathi Basin=Bacino d'Arathi⟧.", 0x1b6fa606, nil, nil, nil, 0x84b7e476, ".mmm." },
  [8567] = { "Vittorie passate nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧", nil, nil, nil, "Ah, sì! Certo che non ci saremmo dimenticati delle tue imprese passate nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧.", 0x2097f0b6, nil, nil, nil, 0xbc373b8c, ".mmm." },
  [8568] = { "Vittorie passate nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧", nil, nil, nil, "Ah, sì! Certo che non ci saremmo dimenticati delle tue imprese passate nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧.", 0x2097f0b6, nil, nil, nil, 0xbc373b8c, ".mmm." },
  [8569] = { "Sforzi passati nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧", nil, nil, nil, "Ah, sì! Certo che non ci saremmo dimenticati delle tue imprese passate nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧.", 0xddd58d46, nil, nil, nil, 0xbc373b8c, ".mmm." },
  [8570] = { "Sforzi passati nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧", nil, nil, nil, "Ah, sì! Certo che non ci saremmo dimenticati delle tue imprese passate nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧.", 0xddd58d46, nil, nil, nil, 0xbc373b8c, ".mmm." },
  [8744] = { "Un ⟦Carefully Wrapped Present=Regalo Incartato con Cura⟧", nil, nil, nil, "Il biglietto su questo regalo dice:\n\nPer {name},\n\nChe la tua festa di Great-Winter sia allegra e luminosa!", 0x82f6205e, nil, nil, nil, 0x7c551a8a, ".mmm." },
  [8767] = { "Un ⟦Gently Shaken Gift=Dono Dolcemente Scosso⟧", nil, nil, nil, "Sembra che questo regalo sia stato scosso un paio di volte. Il biglietto dice:\n\nA <un/una> {race} {class} davvero speciale.", 0x5c9b9fd0, nil, nil, nil, 0x2725065f, ".mmm." },
  [8768] = { "Un ⟦Gaily Wrapped Present=Regalo Incartato Gioiosamente⟧", nil, nil, nil, "Questo regalo dalla confezione festosa porta il tuo nome.\n\nAspetta... si è appena mosso?", 0xa796cbc4, nil, nil, nil, 0x84f10ae3, ".mmm." },
  [8788] = { "Un ⟦Gently Shaken Gift=Dono Dolcemente Scosso⟧", nil, nil, nil, "Sembra che questo regalo sia stato scosso un paio di volte. Il biglietto dice:\n\nA <un/una> {race} {class} davvero speciale.", 0x5c9b9fd0, nil, nil, nil, 0x2725065f, ".mmm." },
  [8803] = { "Un ⟦Festive Gift=Dono Festivo⟧", nil, nil, nil, "Il biglietto su questo regalo dice:\n\nA {name},\n\ncon la speranza che ti aiuti a diffondere calorosi auguri e allegria festiva in tutta Azeroth.\n\nDa Greatfather Winter", 0xb44e34d8, nil, nil, nil, 0x2f05f323, ".mmm." },
  [8827] = { "I regali dell'inverno", "Parla con Greatfather Winter. Si trova vicino all'area dei venditori di Smokywood Pastures a ⟦Ironforge=Forgiardente⟧.", "Ho sentito che Greatfather Winter, con il generoso sostegno di Smokeywood Pastures, ha messo regali per tutti sotto l'albero a ⟦Ironforge=Forgiardente⟧. Vorrei tanto andarci, ma devo badare al ⟦PX-238 Winter Wondervolt=Trasmutometro Invernale PX-238⟧.\n\nMa tu dovresti proprio andare a vedere. Sono sicuro che Greatfather Winter ha qualche regalo con il tuo nome sopra.", nil, "Oh, oh, salve! Puoi essere qui per un solo motivo: aprire i tuoi regali di Winter Veil.\n\nOra, non preoccuparti, Greatfather Winter non si è dimenticato <del/della> <suo/sua> {race} {class} preferit<o/a>. Guarda sotto l'albero e troverai i tuoi doni.\n\nIn questa stagione di regali, forse anche ai tuoi amici farebbe piacere ricevere qualcuno degli ottimi prodotti di Smokeywood Pastures?", 0xe0911411, 0x24244a23, 0xd280792a, nil, 0xbcb9cdb9, "...m." },
  [8828] = { "I regali dell'inverno", "Parla con Great-father Winter. Si trova vicino all'area dei venditori di Smokywood Pastures a Orgrimmar.", "Ho sentito che Great-father Winter, con il generoso sostegno di Smokeywood Pastures, ha messo regali per tutti sotto l'albero a Orgrimmar. Vorrei tanto andarci, ma devo badare al ⟦PX-238 Winter Wondervolt=Trasmutometro Invernale PX-238⟧.\n\nMa tu dovresti proprio andare a vedere. Sono sicuro che Great-father Winter ha qualche regalo con il tuo nome sopra.", nil, "Oh, oh, salve! Puoi essere qui per un solo motivo: aprire i tuoi regali di Winter Veil.\n\nOra, non preoccuparti, Great-father Winter non si è dimenticato <del/della> <suo/sua> {race} {class} preferit<o/a>. Guarda sotto l'albero e troverai i tuoi doni.\n\nIn questa stagione di regali, forse anche ai tuoi amici farebbe piacere ricevere qualcuno degli ottimi prodotti di Smokeywood Pastures?", 0xe0911411, 0xa2c904f5, 0x12f578d8, nil, 0xb8f8924f, "...m." },
  [8846] = { "Cinque sigilli per i rifornimenti di guerra", nil, nil, "Ah, sei qui per altri rifornimenti per te, vero? Beh, capisco bene il bisogno di altro materiale... basta che ti guardi intorno, se ti serve una prova.\n\nTi darò altri rifornimenti, ma in cambio dovrai consegnarmi un numero adeguato di sigilli di encomio. Non riceverai alcun riconoscimento per aver ceduto i sigilli in questo modo, ma potresti trovare qualcosa di utile che ti aiuti a restare viv<o/a> quando la battaglia sarà finalmente arrivata.", "Bene allora, è deciso: ecco i tuoi rifornimenti, {class}. Se desideri fare un altro scambio, sono pronto ad autorizzarlo. Basta che tu me lo dica e lo farò.\n\nContinua così, {name}. Ci serve tutto il materiale che riusciamo a raccogliere se vogliamo vincere questa guerra. Se ognuno fa la sua parte, la vittoria sarà nostra!", 0x87ab84fa, nil, nil, 0x44b98cd5, 0xb2839001, ".mm.." },
  [8847] = { "Dieci sigilli per i rifornimenti di guerra", nil, nil, "Ah, sei qui per altri rifornimenti per te, vero? Beh, capisco bene il bisogno di altro materiale... basta che ti guardi intorno, se ti serve una prova.\n\nTi darò altri rifornimenti, ma in cambio dovrai consegnarmi un numero adeguato di sigilli di encomio. Non riceverai alcun riconoscimento per aver ceduto i sigilli in questo modo, ma potresti trovare qualcosa di utile che ti aiuti a restare viv<o/a> quando la battaglia sarà finalmente arrivata.", "Bene allora, è deciso: ecco i tuoi rifornimenti, {class}. Se desideri fare un altro scambio, sono pronto ad autorizzarlo. Basta che tu me lo dica e lo farò.\n\nContinua così, {name}. Ci serve tutto il materiale che riusciamo a raccogliere se vogliamo vincere questa guerra. Se ognuno fa la sua parte, la vittoria sarà nostra!", 0x742d2884, nil, nil, 0x44b98cd5, 0xb2839001, ".mm.." },
